import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import cp from 'node:child_process';
import {syncBuiltinESMExports} from 'node:module';
import {Persistence} from '@tileset/persistence';
const conf=JSON.parse(await readFile(process.argv[2],'utf8')),resources=JSON.parse(await readFile('apps/api/dist/resources/studio.json','utf8'));const original=cp.fork;let forks=0;cp.fork=function(...args){forks++;return original.apply(this,args);};syncBuiltinESMExports();const store=new Persistence(conf.database,conf.assets,resources.profile);
try{const row=await store.db.assetRevision.findFirstOrThrow({where:{kind:'recipe'},orderBy:{revision:'asc'}});const start=performance.now();const restored=await store.readDomainRecipe(row.projectId,row.id);const output={source:resources.context.commit,wallMs:Math.round(performance.now()-start),actualNativeForks:forks,sourceCount:restored.sources.length,irHash:restored.built.ir.contentHash,artifactHash:restored.built.artifactHash,sourceRefs:restored.sources.map(s=>s.ref),encoding:restored.sources.map(s=>s.raw.encoding),state:'actual public readDomainRecipe completed; not synthetic owned objects'};await writeFile(process.argv[3],JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify({forks,ms:output.wallMs,sources:output.sourceCount,irHash:output.irHash}));}finally{await store.close();cp.fork=original;syncBuiltinESMExports();}
